package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func check(value string) string {
	if value[0] == '.' {
		value = "dot" + value[1:]
	} else if value[0] == '@' {
		value = "at" + value[1:]
	}

	if value[len(value)-1] == '.' {
		value = value[:len(value)-1] + "dot"
	} else if value[len(value)-1] == '@' {
		value = value[:len(value)-1] + "at"
	}

	return value
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var s string
	fmt.Fscan(in, &s)

	var result strings.Builder

	for i := 0; i < len(s); i++ {
		if i+3 <= len(s) && s[i:i+3] == "dot" {
			result.WriteByte('.')
			i += 2
		} else if i+2 <= len(s) && s[i:i+2] == "at" {
			result.WriteByte('@')
			i++
		} else {
			result.WriteByte(s[i])
		}
	}

	solved := check(result.String())
	count := strings.Count(solved, "@")

	if count == 1 {
		fmt.Fprintln(out, solved)
		return
	}

	var answer strings.Builder
	first := true

	for i := 0; i < len(solved); i++ {
		if solved[i] == '@' {
			if first {
				answer.WriteByte('@')
				first = false
			} else {
				answer.WriteString("at")
			}
		} else {
			answer.WriteByte(solved[i])
		}
	}

	fmt.Fprintln(out, answer.String())
}

